//! Cassette replay parity for the Open Responses / `OpenAI` Responses lanes.
//!
//! Expected dumps were generated by driving the REAL v2 step machines
//! (`/tmp/opencode/ref/packages/ai`, script at `/tmp/opencode/ai-dump/dump.mjs`)
//! over every `*responses*` cassette group minus the deferred websocket group:
//! 52 HTTP interactions across `openai-responses`, `openai-responses-cache`,
//! `openai-responses-images`, `moonshot-responses`, `minimax-responses`,
//! `meta-responses`, `alibaba-responses` → 1349 common events.
//!
//! This test replays each recorded body through the production
//! [`FramingDecoder`] and the Rust step machines and requires an exact match
//! of frames, events, and terminal handling.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use serde_json::Value;

use oc_ai::protocols::open_responses::{
    open_responses_route, OpenResponsesProtocol, OpenResponsesRouteSpec, ParserState,
};
use oc_ai::protocols::openai_responses::{
    openai_responses_route, OpenAIResponsesProtocol, OpenAIResponsesRouteSpec,
};
use oc_ai::route::framing::{Framing, FramingDecoder};
use oc_ai::route::transport::FailingTransport;
use oc_ai::schema::{AiError, AiErrorReason, LLMEvent, LLMRequest};

fn expected_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("test-fixtures/expected")
}

fn recordings_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("test-fixtures/recordings")
}

/// One machine configuration per cassette group (mirrors the dump script).
struct GroupSpec {
    prefix: &'static str,
    openai: bool,
    provider: &'static str,
    key: &'static str,
}

const GROUPS: &[GroupSpec] = &[
    GroupSpec { prefix: "openai-responses", openai: true, provider: "openai", key: "openai" },
    GroupSpec { prefix: "openai-responses-cache", openai: true, provider: "openai", key: "openai" },
    GroupSpec {
        prefix: "openai-responses-images",
        openai: true,
        provider: "openai",
        key: "openai",
    },
    GroupSpec {
        prefix: "moonshot-responses",
        openai: false,
        provider: "moonshot",
        key: "moonshot",
    },
    GroupSpec { prefix: "minimax-responses", openai: false, provider: "minimax", key: "minimax" },
    GroupSpec { prefix: "meta-responses", openai: false, provider: "meta", key: "meta" },
    GroupSpec { prefix: "alibaba-responses", openai: false, provider: "alibaba", key: "alibaba" },
];

fn dump_files(root: &Path, out_dir: &str, prefix: &str) -> Vec<PathBuf> {
    let mut files: Vec<PathBuf> = std::fs::read_dir(root.join(out_dir).join(prefix))
        .into_iter()
        .flatten()
        .map(|entry| entry.unwrap().path())
        .filter(|path| path.extension().and_then(|ext| ext.to_str()) == Some("json"))
        .collect();
    files.sort();
    files
}

fn request_for(group: &GroupSpec) -> LLMRequest {
    let transport = Arc::new(FailingTransport { message: "machine-level replay" });
    let route = if group.openai {
        openai_responses_route(OpenAIResponsesRouteSpec {
            base_url: Some("https://responses.test/v1".into()),
            auth: None,
            transport,
            defaults: oc_ai::route::RouteDefaults::default(),
        })
    } else {
        open_responses_route(OpenResponsesRouteSpec {
            id: "dump-responses".into(),
            provider: group.provider.into(),
            provider_metadata_key: Some(group.key.into()),
            base_url: "https://responses.test/v1".into(),
            auth: None,
            transport,
            defaults: oc_ai::route::RouteDefaults::default(),
        })
    };
    let model = route.model("test-model", None).expect("model");
    LLMRequest::new(model).with_prompt("hi")
}

/// Decode an SSE body exactly like the route pipeline does.
fn decode_frames(body: &str) -> Vec<String> {
    let mut decoder = FramingDecoder::new(Framing::sse());
    let mut frames = decoder.feed(body.as_bytes()).expect("frames decode");
    frames.extend(decoder.finish().expect("frames finish"));
    frames
}

#[tokio::test]
async fn open_responses_cassette_replay_matches_expected_dumps() {
    let mut checked = 0;
    let mut total_events = 0;
    for group in GROUPS.iter().filter(|group| !group.openai) {
        for dump_path in dump_files(&expected_root(), "open-responses", group.prefix) {
            let dump: Value =
                serde_json::from_str(&std::fs::read_to_string(&dump_path).unwrap()).unwrap();
            let scenario = dump["scenario"].as_str().unwrap();
            let interaction = dump["interaction"].as_u64().unwrap();
            let body = recorded_body(group.prefix, scenario, interaction);
            let frames = decode_frames(&body);
            assert_eq!(
                serde_json::to_value(&frames).unwrap(),
                dump["frames"],
                "frames diverge: {}",
                dump_path.display()
            );

            let request = request_for(group);
            let protocol =
                OpenResponsesProtocol::new(Arc::new(oc_ai::protocols::open_responses::BaseAdapter));
            let mut state =
                ParserState::new(&request, &oc_ai::protocols::open_responses::BaseAdapter);
            let mut events = Vec::new();
            let mut outcome: Result<(), String> = Ok(());
            'frames: for frame in &frames {
                match protocol.step_frame(&mut state, frame) {
                    Ok((emitted, terminal)) => {
                        events.extend(emitted);
                        if terminal {
                            break 'frames;
                        }
                    }
                    Err(error) => {
                        outcome = Err(format!("unexpected step error: {}", error.message()));
                        break 'frames;
                    }
                }
            }
            assert!(outcome.is_ok(), "{}: {:?}", dump_path.display(), outcome);
            assert!(
                dump["error"].is_null(),
                "{}: dump recorded an error; rerun the generator",
                dump_path.display()
            );
            let actual: Vec<Value> = events.iter().map(event_wire).collect();
            assert_json_equal(
                &serde_json::to_value(&actual).unwrap(),
                &dump["events"],
                &dump_path.display().to_string(),
            );
            total_events += events.len();
            checked += 1;
        }
    }
    assert_eq!(checked, 42, "expected the 42 base-machine interactions");
    assert_eq!(total_events, 1_072);
}

#[tokio::test]
async fn openai_responses_cassette_replay_matches_expected_dumps() {
    let mut checked = 0;
    let mut total_events = 0;
    for group in GROUPS.iter().filter(|group| group.openai) {
        for dump_path in dump_files(&expected_root(), "openai-responses", group.prefix) {
            let dump: Value =
                serde_json::from_str(&std::fs::read_to_string(&dump_path).unwrap()).unwrap();
            let scenario = dump["scenario"].as_str().unwrap();
            let interaction = dump["interaction"].as_u64().unwrap();
            let body = recorded_body(group.prefix, scenario, interaction);
            let frames = decode_frames(&body);
            assert_eq!(
                serde_json::to_value(&frames).unwrap(),
                dump["frames"],
                "frames diverge: {}",
                dump_path.display()
            );

            let request = request_for(group);
            let protocol = OpenAIResponsesProtocol;
            let mut state =
                ParserState::new(&request, &oc_ai::protocols::openai_responses::OpenAIAdapter);
            let mut events = Vec::new();
            let mut outcome: Result<(), String> = Ok(());
            'frames: for frame in &frames {
                match protocol.step_frame(&mut state, frame) {
                    Ok((emitted, terminal)) => {
                        events.extend(emitted);
                        if terminal {
                            break 'frames;
                        }
                    }
                    Err(error) => {
                        outcome = Err(format!("unexpected step error: {}", error.message()));
                        break 'frames;
                    }
                }
            }
            assert!(outcome.is_ok(), "{}: {:?}", dump_path.display(), outcome);
            assert!(
                dump["error"].is_null(),
                "{}: dump recorded an error; rerun the generator",
                dump_path.display()
            );
            let actual: Vec<Value> = events.iter().map(event_wire).collect();
            assert_json_equal(
                &serde_json::to_value(&actual).unwrap(),
                &dump["events"],
                &dump_path.display().to_string(),
            );
            total_events += events.len();
            checked += 1;
        }
    }
    assert_eq!(checked, 10, "expected the 10 openai-machine interactions");
    assert_eq!(total_events, 277);
}

fn recorded_body(prefix: &str, scenario: &str, interaction: u64) -> String {
    let path = recordings_root().join(prefix).join(format!("{scenario}.json"));
    let cassette = oc_ai::test_support::Cassette::load(&path).expect("cassette parses");
    let interactions: Vec<_> = cassette.http_interactions().collect();
    interactions[usize::try_from(interaction).expect("interaction index")]
        .response
        .as_ref()
        .and_then(|response| response.body.clone())
        .unwrap_or_default()
}

// ---------------------------------------------------------------------------
// Event wire serialization — native serde (the LLMEvent tree serializes in
// the TS contract shape: camelCase fields, None dropped), the parity
// counterpart of `JSON.stringify(event)` in the dump.
// ---------------------------------------------------------------------------

fn event_wire(event: &LLMEvent) -> Value {
    serde_json::to_value(event).expect("LLMEvent serializes in the TS wire shape")
}

// ---------------------------------------------------------------------------
// Number-coercing JSON equality (JS treats 0 and 0.0 as the same number;
// serde_json distinguishes integer and float representations).
// ---------------------------------------------------------------------------

fn assert_json_equal(actual: &Value, expected: &Value, context: &str) {
    if json_equal(actual, expected) {
        return;
    }
    // Find the first divergence for a readable failure.
    let mut path = String::from("$");
    find_divergence(actual, expected, &mut path);
    panic!("event divergence at {path} ({context})\nactual:   {actual}\nexpected: {expected}");
}

fn json_equal(actual: &Value, expected: &Value) -> bool {
    match (actual, expected) {
        (Value::Number(a), Value::Number(b)) => match (a.as_f64(), b.as_f64()) {
            // exact equality is the point: both sides computed the same math
            #[allow(clippy::float_cmp)]
            (Some(a), Some(b)) => a == b,
            _ => a == b,
        },
        (Value::Object(a), Value::Object(b)) => {
            a.len() == b.len()
                && a.iter()
                    .all(|(key, value)| b.get(key).is_some_and(|other| json_equal(value, other)))
        }
        (Value::Array(a), Value::Array(b)) => {
            a.len() == b.len() && a.iter().zip(b).all(|(x, y)| json_equal(x, y))
        }
        _ => actual == expected,
    }
}

fn find_divergence(actual: &Value, expected: &Value, path: &mut String) {
    use std::fmt::Write as _;
    match (actual, expected) {
        (Value::Object(a), Value::Object(b)) => {
            for (key, value) in a {
                match b.get(key.as_str()) {
                    Some(other) if json_equal(value, other) => continue,
                    Some(other) => {
                        let _ = write!(path, ".{key}");
                        find_divergence(value, other, path);
                    }
                    None => {
                        let _ = write!(path, ".{key} (missing in expected)");
                    }
                }
                break;
            }
        }
        (Value::Array(a), Value::Array(b)) => {
            for (index, (x, y)) in a.iter().zip(b).enumerate() {
                if !json_equal(x, y) {
                    let _ = write!(path, "[{index}]");
                    find_divergence(x, y, path);
                    return;
                }
            }
        }
        _ => {}
    }
}

/// The dump corpus shape is pinned so a regenerated corpus cannot silently
/// shrink.
#[test]
fn open_responses_expected_corpus_shape() {
    let base = dump_files(&expected_root(), "open-responses", "moonshot-responses").len()
        + dump_files(&expected_root(), "open-responses", "minimax-responses").len()
        + dump_files(&expected_root(), "open-responses", "meta-responses").len()
        + dump_files(&expected_root(), "open-responses", "alibaba-responses").len();
    let openai = dump_files(&expected_root(), "openai-responses", "openai-responses").len()
        + dump_files(&expected_root(), "openai-responses", "openai-responses-cache").len()
        + dump_files(&expected_root(), "openai-responses", "openai-responses-images").len();
    assert_eq!(base, 42, "base machine interactions");
    assert_eq!(openai, 10, "openai machine interactions");
}

/// Errors classify identically to the TS `providerFailure` (unit parity for
/// the error frames the corpus happens not to contain).
#[test]
fn open_responses_provider_failure_matches_the_ts_shapes() {
    use oc_ai::protocols::open_responses::{error_detail, provider_failure, Event};

    let decode = |raw: &str| {
        let value: serde_json::Value = serde_json::from_str(raw).unwrap();
        let kind =
            value.get("type").and_then(serde_json::Value::as_str).unwrap_or_default().to_string();
        Event { raw: value, kind }
    };
    let cases: Vec<(&str, &str, &str)> = vec![
        (
            r#"{"type":"error","code":"server_shutting_down","message":"Shutting down"}"#,
            "server_shutting_down: Shutting down",
            "UnknownProvider",
        ),
        (r#"{"type":"error","error":"Gateway failed"}"#, "Gateway failed", "UnknownProvider"),
        (
            r#"{"type":"error","error":{"code":429,"message":"slow down"}}"#,
            "429: slow down",
            "UnknownProvider",
        ),
        (
            r#"{"type":"error","error":{"message":"slow down"},"status":429}"#,
            "slow down",
            "RateLimit",
        ),
        (r#"{"type":"error","code":500,"message":["not","a","string"]}"#, "500", "UnknownProvider"),
        (
            r#"{"type":"response.failed","response":{"id":"resp_failed","error":"Gateway failed"}}"#,
            "Gateway failed",
            "UnknownProvider",
        ),
    ];
    for (raw, message, tag) in cases {
        let event = decode(raw);
        let error = provider_failure(&event, "fallback", None);
        assert_eq!(error.message(), message, "message for {raw}");
        assert_eq!(error.tag(), tag, "tag for {raw}");
    }
    let bare = decode(r#"{"type":"error"}"#);
    let error = provider_failure(&bare, "fallback", Some("{}"));
    assert_eq!(error.message(), "fallback");
    assert_eq!(error.tag(), "ProviderInternal");

    let (message, code) = error_detail(&decode(
        r#"{"type":"error","sequence_number":4,"code":"server_shutting_down","message":"Shutting down","param":null}"#,
    ));
    assert_eq!(message.as_deref(), Some("Shutting down"));
    assert_eq!(code.as_deref(), Some("server_shutting_down"));
}

/// `AiError` classification field is readable for parity assertions.
#[test]
fn open_responses_classification_extraction() {
    let error = AiError::new(AiErrorReason::InvalidRequest {
        fields: oc_ai::schema::ReasonFields::new("too big"),
        parameter: None,
        classification: Some(oc_ai::schema::ProviderFailureClassification::ContextOverflow),
    });
    match &error.reason {
        AiErrorReason::InvalidRequest { classification, .. } => {
            assert_eq!(
                serde_json::to_value(classification).unwrap(),
                serde_json::Value::String("context-overflow".into())
            );
        }
        other => panic!("unexpected reason {}", other.tag()),
    }
}
